-- Replace the original generic starter recipes while preserving any user-added recipes.
BEGIN;
DELETE FROM recipes WHERE name IN (
 'Tomato Egg Scramble','Garlic Tomato Pasta','Simple Pancakes','Cheese Omelette',
 'Banana Oat Bowl','Garlic Fried Rice','Tomato Cheese Toast','Lemon Garlic Pasta',
 'Apple Oat Porridge','Egg Fried Rice','Cheesy Tomato Pasta','Banana Pancakes',
 'Tomato Rice','Apple Pancakes','Garlic Cheese Toast','Tomato Egg Rice',
 'Banana Milk Smoothie','Cheese Pasta'
);

ON CONFLICT(name) DO NOTHING;
COMMIT;
